public int NumIslands(char[][] grid)
{
    int m = grid.Length, n = grid[0].Length;
    int count = 0;
    for (int i = 0; i < m; i++)
        for (int j = 0; j < n; j++)
            if (grid[i][j] == '1')
            {
                count++;
                DFS(grid, i, j);
            }
    return count;
}

private void DFS(char[][] grid, int i, int j)
{
    if (i < 0 || j < 0 || i >= grid.Length || j >= grid[0].Length || grid[i][j] != '1')
        return;
    grid[i][j] = '0';
    DFS(grid, i + 1, j);
    DFS(grid, i - 1, j);
    DFS(grid, i, j + 1);
    DFS(grid, i, j - 1);
}
